# Let me analyze the actual pattern by looking at each grid cell
def count_nan(grid, row, col):
    """Give some unique ID based on anti-diagonal position"""
    return grid[row][col]

def categorize_diagonal(grid):
    """Categorize by row - for Demo 2 it was rows, for this maybe anti-diagonals"""
    height, width = len(grid), len(grid[0])

    # Find all unique non-zero cells with their (row, col, value)
    cells = []
    for r in range(height):
        for c in range(width):
            if grid[r][c] != 0:
                cells.append((r, c, grid[r][c]))

    print(f"Found {len(cells)} non-zero cells")

    # Group by anti-diagonal
    anti_diag_entries = {}
    for r, c, val in cells:
        key = (r + c) % (width + 1)  # Mod by width+1 to get limited categories
        if key not in anti_diag_entries:
            anti_diag_entries[key] = []
        anti_diag_entries[key].append(val)

    # Get unique per category
    unique_values = [sorted(set(anti_diag_entries[key])) for key in sorted(anti_diag_entries.keys())]
    print(f"\nCategories by (r+c) % {width+1}:")
    for key in sorted(anti_diag_entries.keys()):
        sorted_vals = sorted(set(anti_diag_entries[key]))
        print(f"  {key}: {anti_diag_entries[key]} -> unique={sorted_vals}")

    return unique_values

