import json

def check_transform_output(n):
    """Check if transform with mod n produces the correct output"""
    height, width = len(test_input), len(test_input[0])

    # Anti-diagonal sums based on paired pattern
    anti_diag_pattern = {}
    for r in range(height):
        for c in range(width):
            val = test_input[r][c]
            if val != 0:
                if (r + c) not in anti_diag_pattern:
                    anti_diag_pattern[r + c] = set()
                anti_diag_pattern[r + c].add(val)

    # Get first value for each anti-diagonal
    values = [sorted(anti_diag_pattern[s])[0] for s in sorted(anti_diag_pattern.keys())]

    # Find minimum sum
    min_sum = min(anti_diag_pattern.keys())

    # Generate output using mod n
    output = []
    for r in range(height):
        row_out = []
        for c in range(width):
            idx = (r + c - min_sum) % n
            row_out.append(values[idx])
        output.append(row_out)

    return output

